const $ = s => document.querySelector(s);
const safe = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db;try{db=JSON.parse(localStorage.getItem('passo-v1'))}catch{};
const fresh = name => ({name,xp:0,done:[],days:{},reviews:{},mistakes:[],goal:30});
if(!db||!Array.isArray(db.profiles))db={active:0,profiles:[fresh('Matheus'),fresh('Minha parceira')]};
let page='home',category='Backend',session=null;
const person=()=>db.profiles[db.active];
const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function save(){try{localStorage.setItem('passo-v1',JSON.stringify(db))}catch{toast('Seu navegador não conseguiu salvar. Exporte um backup em Ajustes.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function streak(p){let d=new Date(),n=0;if(!p.days[dayKey(d)])d.setDate(d.getDate()-1);while(p.days[dayKey(d)]){n++;d.setDate(d.getDate()-1)}return n}
const next=()=>lessons.findIndex((_,i)=>!person().done.includes(i));
const art=`<svg viewBox="0 0 180 180" fill="none" aria-hidden="true"><circle cx="94" cy="94" r="76" fill="#e0e8cf"/><path d="M35 133L92 154L150 124L93 103Z" fill="#c0cdb0"/><path d="M46 111L94 129L143 106L95 88Z" fill="#fcfcf1"/><path d="M46 111V121L94 140V129Z" fill="#e7e9d6"/><path d="M94 129L143 106V116L94 140Z" fill="#adbf9d"/><path d="M53 93L95 109L138 89L96 73Z" fill="#8da77c"/><path d="M53 93V103L95 119V109Z" fill="#6f8c60"/><path d="M95 109L138 89V99L95 119Z" fill="#4e7251"/><path d="M95 76C65 68 67 38 69 29C92 32 103 49 95 76Z" fill="#5e835a"/><path d="M96 76C96 48 116 40 132 43C132 64 115 79 96 76Z" fill="#91aa75"/><path d="M95 91V55" stroke="#496e4c" stroke-width="3" stroke-linecap="round"/><path d="M37 55L40 48L43 55L50 58L43 61L40 68L37 61L30 58Z" fill="#bba86b"/><circle cx="143" cy="37" r="4" fill="#c8b477"/><circle cx="150" cy="142" r="3" fill="#b4c29d"/></svg>`;
function week(){let d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7));return ['S','T','Q','Q','S','S','D'].map((label,i)=>{let x=new Date(d);x.setDate(d.getDate()+i);return `<div class="day">${label}<b class="${person().days[dayKey(x)]?'hit':''}">${person().days[dayKey(x)]?'✓':x.getDate()}</b></div>`}).join('')}
function rail(){let p=person(),today=p.days[dayKey()]||0,duo=db.profiles.filter(x=>x.days[dayKey()]).length;return `<aside class="rail"><section class="panel"><div class="goal-top"><div><h3>Sua meta de hoje</h3><p>${today} de ${p.goal} XP<br>Um passo de cada vez.</p></div><div class="ring" style="--value:${Math.min(100,today/p.goal*100)}"><strong>${Math.round(Math.min(100,today/p.goal*100))}%</strong></div></div><div class="week">${week()}</div></section><section class="panel"><span class="eyebrow">Melhor em dupla</span><div class="duo-avatars"><span class="avatar">${safe(db.profiles[0].name[0])}</span><span class="avatar pink">${safe(db.profiles[1].name[0])}</span></div><h3>Dois caminhos. Uma parceria.</h3><p>Que tal cada um concluir uma aula hoje?</p><div class="duo-bar"><span class="${duo>0?'hit':''}"></span><span class="${duo>1?'hit':''}"></span></div><div class="small muted">${duo}/2 pessoas estudaram hoje</div><button class="linkbtn" data-page="duo" style="margin-top:18px;padding:0">Ver nossa dupla ↗</button></section><section class="panel quote"><p>“Grandes jornadas começam com pequenos passos.”</p><small>MENOS PRESSA. MAIS CONSTÂNCIA.</small></section></aside>`}
function path(){let p=person(),n=next();return `<div class="track-card"><div class="track-head"><div class="track-icon">⌘</div><div><h3>Backend mais sólido</h3><span class="small muted">Java + Spring Boot · 30 semanas</span></div><span class="badge">SUA TRILHA</span></div><div class="unit"><span class="unit-label">Etapa 01 · Semanas 1–3</span><h3>Internet, HTTP e redes</h3><div class="progress"><span style="width:${p.done.length/lessons.length*100}%"></span></div><p class="small muted">${p.done.length} de ${lessons.length} aulas iniciais concluídas</p></div><div class="path">${lessons.map((l,i)=>`<button class="lesson-row ${p.done.includes(i)?'done':i===n?'current':''}" data-lesson="${i}" ${i>n&&n!==-1&&!p.done.includes(i)?'disabled':''}><span class="node">${p.done.includes(i)?'✓':i===n?l.icon:'·'}</span><span><strong>${safe(l.title)}</strong><span class="small">${l.time} min · ${p.done.includes(i)?'Concluída · revisar':i===n?'Teoria + 3 questões · 30 XP':'Conclua a aula anterior'}</span></span><span class="arrow">${i===n?'→':''}</span></button>`).join('')}</div></div>`}
function home(){let p=person(),n=next();return `<div class="greeting"><div><span class="eyebrow">Seu espaço para evoluir</span><h1>Um novo dia, um novo passo<span style="color:#9bad7e">.</span></h1><p>Vamos aprender um pouco hoje, ${safe(p.name)}?</p></div><span class="date-chip">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</span></div><div class="columns"><div><section class="hero"><div><span class="eyebrow">${n===-1?'Etapa inicial concluída':'Sua próxima pequena vitória'}</span><h2>${n===-1?'O conhecimento cresce com a prática.':'Desvende o caminho de uma requisição.'}</h2><p>${n===-1?'Revisite suas aulas e mantenha o ritmo.':n===0?'Do primeiro clique até a sua API. Vamos começar?':`Continue com: ${safe(lessons[n].title)}.`}</p><button class="btn" data-lesson="${n===-1?0:n}">${n===-1?'Revisar uma aula':n===0?'Começar minha jornada':'Continuar minha jornada'} <span>→</span></button></div><div class="hero-art">${art}</div></section><div class="section-title"><h2>Sua trilha de aprendizado</h2><button class="linkbtn" data-page="trails">Ver todas as trilhas ↗</button></div>${path()}<div class="footer-note">30–45 minutos por dia · 5 dias por semana · No seu ritmo</div></div>${rail()}</div>`}
function trails(){return `<span class="eyebrow">Escolha seu próximo passo</span><h1>Um mundo para aprender.</h1><p class="muted">Uma trilha por vez, sem deixar a curiosidade de lado.</p><div class="tabrow">${['Backend','Odontologia','Concursos','Meus temas'].map(x=>`<button data-category="${x}" class="${category===x?'selected':''}">${x}</button>`).join('')}</div>${category==='Backend'?`<div class="notes" style="margin-bottom:20px">Seu plano de 30 semanas está organizado abaixo. As primeiras 6 aulas de redes estão disponíveis; as demais etapas são o planejamento e ainda precisam receber conteúdo.</div><div class="cards">${stages.map((s,i)=>`<article class="stage"><div class="track-icon">${s[3]}</div><span class="eyebrow">ETAPA ${String(i+1).padStart(2,'0')} · ${s[1]}</span><h3 style="margin-top:10px">${s[0]}</h3><p>${s[2]}</p>${i===0?'<button class="linkbtn" data-page="home">Abrir as 6 aulas disponíveis →</button>':'<span class="small muted">Planejada · conteúdo em preparação</span>'}</article>`).join('')}</div><p class="small muted">Estrutura baseada no plano que você enviou. <a href="https://roadmap.sh/backend" target="_blank" rel="noopener">Consultar o roadmap de backend ↗</a></p>`:category==='Meus temas'?`<div class="panel"><h2>Seu espaço de curiosidade</h2><p>Guarde temas que vocês querem estudar. Eles aparecem neste navegador.</p><form id="topic-form"><div class="formrow"><label for="topic">Novo tema</label><input id="topic" name="topic" required maxlength="100" placeholder="Ex.: espanhol, matemática, finanças"></div><button class="btn">Adicionar tema +</button></form><div style="margin-top:24px">${(db.topics||[]).map((t,i)=>`<p>${safe(t)} <button data-delete="${i}" aria-label="Excluir ${safe(t)}">×</button></p>`).join('')}</div></div>`:`<div class="empty"><div style="font-size:40px">${category==='Odontologia'?'✧':'▤'}</div><h2>${category==='Odontologia'?'Uma trilha com a cara dela.':'Um objetivo de cada vez.'}</h2><p>${category==='Odontologia'?'Espaço reservado para as matérias, especialidade e objetivos dela.':'As trilhas serão montadas a partir do concurso, cargo e edital de vocês.'}</p><p class="small">Ainda não há aulas nesta área. Envie os temas no chat para montarmos o conteúdo.</p></div>`}`}
function review(){let p=person();return `<span class="eyebrow">Repetir é consolidar</span><h1>Faça o conhecimento ficar.</h1><p class="muted">Revise o que já estudou. Uma revisão por aula, por dia, rende 5 XP.</p>${p.done.length?`<div class="cards">${p.done.map(i=>`<div class="stage"><span class="eyebrow">REVISÃO · 3 QUESTÕES</span><h2>${lessons[i].title}</h2><p>${p.reviews[i]===dayKey()?'Revisada hoje. Você ainda pode praticar.':'Recupere os conceitos sem olhar a teoria.'}</p><button class="btn secondary" data-review="${i}">Praticar →</button></div>`).join('')}</div>`:'<div class="empty"><h2>A prática começa com a primeira aula.</h2><p>Quando concluir uma aula, ela aparecerá aqui para revisão.</p><button class="btn" data-lesson="0">Começar primeira aula →</button></div>'}${p.mistakes.length?`<h2 style="margin-top:30px">Pontos para reforçar</h2>${p.mistakes.map(m=>`<div class="panel" style="margin-bottom:10px"><h3>${safe(lessons[m.l].qs[m.q][0])}</h3><p>${safe(lessons[m.l].qs[m.q][3])}</p><button class="linkbtn" data-review="${m.l}">Revisar essa aula →</button></div>`).join('')}`:''}`}
function progressPage(){let p=person();return `<span class="eyebrow">Cada passo conta</span><h1>Olha o quanto você caminhou.</h1><div class="cards"><div class="panel"><h3>Experiência acumulada</h3><div class="metric">${p.xp} <span class="small muted">XP</span></div><p>Nível ${Math.floor(p.xp/150)+1} · ${150-p.xp%150} XP para o próximo nível</p><div class="progress"><span style="width:${p.xp%150/150*100}%"></span></div></div><div class="panel"><h3>Seu ritmo</h3><div class="metric">${streak(p)} <span class="small muted">dias seguidos</span></div><p>${Object.keys(p.days).length} dias de estudo no total · ${p.done.length} aulas concluídas</p></div></div><h2 style="margin-top:30px">Pequenas conquistas</h2><div class="cards">${[['✧','Primeiro passo','Conclua sua primeira aula',p.done.length>0],['♨','Criando raízes','Estude por 3 dias seguidos',streak(p)>=3],['⌘','Conexão estabelecida','Conclua as 6 aulas de redes',p.done.length===6],['☆','Mente em movimento','Acumule 150 XP',p.xp>=150]].map(a=>`<div class="panel" style="opacity:${a[3]?1:.55}"><div class="track-icon">${a[0]}</div><h3 style="margin-top:15px">${a[1]} ${a[3]?'✓':''}</h3><p>${a[2]}</p><span class="small muted">${a[3]?'Conquistada':'A caminho'}</span></div>`).join('')}</div>`}
function duo(){return `<span class="eyebrow">Um incentiva o outro</span><h1>Juntos, no próprio ritmo.</h1><p class="muted">Aqui a parceria vale mais que a competição.</p><div class="cards">${db.profiles.map((p,i)=>`<div class="panel"><span class="avatar ${i?'pink':''}">${safe(p.name[0])}</span><h2>${safe(p.name)}</h2><p>${p.xp} XP · ${p.done.length} aulas · ${streak(p)} dias seguidos</p><div class="progress"><span style="width:${Math.min(100,(p.days[dayKey()]||0)/p.goal*100)}%"></span></div><p>Hoje: ${p.days[dayKey()]||0} de ${p.goal} XP</p><button class="btn secondary" data-profile="${i}">${i===db.active?'Perfil atual':'Estudar com este perfil'}</button></div>`).join('')}</div><div class="notes" style="margin-top:23px">Nesta versão, os dois perfis ficam neste navegador. A troca de perfil não é um login. A sincronização entre aparelhos ainda não está disponível.</div>`}
function settings(){return `<span class="eyebrow">Do seu jeito</span><h1>Pequenos ajustes, melhor rotina.</h1><section class="panel"><form id="settings-form"><div class="formrow"><label for="name">Nome deste perfil</label><input id="name" name="name" value="${safe(person().name)}" maxlength="35" required></div><div class="formrow"><label for="goal">Meta diária de experiência</label><select name="goal" id="goal">${[30,60,90].map(n=>`<option value="${n}" ${person().goal===n?'selected':''}>${n} XP · ${n/30} aula${n>30?'s':''} por dia</option>`).join('')}</select></div><button class="btn">Salvar ajustes</button></form></section><section class="panel" style="margin-top:18px"><h2>Seu progresso, guardado</h2><p>Os dados ficam somente neste navegador. Exporte uma cópia para guardar ou transferir manualmente para outro aparelho.</p><button class="btn secondary" id="export">Exportar progresso ↓</button><label class="btn secondary" style="cursor:pointer;margin-top:10px">Importar progresso ↑<input type="file" id="import" accept="application/json" hidden></label><p class="small">A importação substitui o progresso local dos dois perfis após confirmação.</p></section>`}
function render(){let p=person();$('#app').innerHTML=`<aside class="sidebar"><div class="logo"><span class="logomark">↗</span>passo</div><div class="tagline">JUNTOS, UM POUCO TODO DIA.</div><nav class="nav">${[['home','⌂','Aprender'],['trails','▤','Trilhas'],['review','⟳','Revisar'],['progress','▥','Progresso'],['duo','♧','Nossa dupla']].map(([v,i,l])=>`<button data-page="${v}" class="${page===v?'active':''}"><i>${i}</i>${l}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="profile" data-page="settings"><span class="avatar ${db.active?'pink':''}">${safe(p.name[0])}</span><span><strong class="small">${safe(p.name)}</strong><br><span class="small muted">Nível ${Math.floor(p.xp/150)+1} · Ajustes</span></span></button><select id="profile" aria-label="Trocar perfil">${db.profiles.map((x,i)=>`<option value="${i}" ${i===db.active?'selected':''}>${safe(x.name)}</option>`).join('')}</select></div></aside><main class="main"><header class="topbar"><span class="crumb">${matchMedia('(max-width:600px)').matches?'passo':'Meu aprendizado / '+({home:'Visão geral',trails:'Trilhas',review:'Revisão',progress:'Progresso',duo:'Nossa dupla',settings:'Ajustes'}[page])}</span><div class="stats"><span title="Dias seguidos"><span class="stat-icon">♨</span>${streak(p)} <span class="small muted">dias</span></span><span title="Experiência acumulada"><span class="stat-icon xp-icon">✦</span>${p.xp} <span class="small muted">XP</span></span><button class="mobile-profile" data-page="settings" aria-label="Abrir ajustes">${safe(p.name[0])}</button></div></header><div class="content">${({home,trails,review,progress:progressPage,duo,settings}[page])()}</div></main>`}
function start(i,rev=false){if(!lessons[i])return;let n=next();if(!rev&&n!==-1&&i>n&&!person().done.includes(i))return;session={i,rev,q:0,selected:null,checked:false,wrong:false,step:rev?'quiz':'read',award:0};showLesson()}
function showLesson(){let s=session,l=lessons[s.i],q=l.qs[s.q];$('#modal').innerHTML=`<div class="overlay"><section role="dialog" aria-modal="true" aria-labelledby="lesson-title" class="dialog"><div class="dialog-head"><span class="eyebrow">${s.step==='read'?'MICROAULA':s.step==='finish'?'PASSO CONCLUÍDO':'PRATICAR'} · INTERNET E REDES</span><button class="close" id="close" aria-label="Fechar aula">×</button></div>${s.step==='read'?`<h2 id="lesson-title">${l.title}</h2><p>${l.text}</p><p>${l.body}</p><div class="code">${safe(l.example)}</div><div class="exercise"><strong>COLOQUE EM PRÁTICA</strong><p>${l.practice}</p></div><div class="dialog-actions"><span class="small muted">${l.time} min · 3 questões</span><button class="btn" id="practice">Entendi, vamos praticar →</button></div>`:s.step==='finish'?`<div class="success"><div class="success-mark">🌱</div><h2 id="lesson-title">Mais um passo dado!</h2><p>${s.rev?'Revisar fortalece o que você já sabe.':'Você transformou curiosidade em conhecimento.'}</p><div class="metric" style="color:var(--green)">+${s.award} XP</div><p class="small">${s.award?'Seu progresso foi salvo neste navegador.':'Esta atividade já rendeu XP. Você pode praticar sempre que quiser.'}</p><button class="btn" id="finish">Voltar para minha trilha →</button></div>`:`<div class="mini-progress">${l.qs.map((_,i)=>`<span class="${i<=s.q?'filled':''}"></span>`).join('')}</div><span class="small muted">Questão ${s.q+1} de ${l.qs.length}</span><h2 id="lesson-title">${q[0]}</h2>${q[1].map((a,i)=>`<button class="answer ${s.selected===i?'selected':''}" data-answer="${i}" ${s.checked?'disabled':''}>${String.fromCharCode(65+i)}. ${safe(a)}</button>`).join('')}${s.checked?`<div class="feedback ${s.wrong?'wrong':''}" role="status"><strong>${s.wrong?'Vamos ajustar esse conceito.':'Isso mesmo!'}</strong><br>${q[3]}</div>`:''}<div class="dialog-actions"><button class="linkbtn" id="theory">Consultar teoria</button><button class="btn" id="check" ${s.selected===null?'disabled':''}>${!s.checked?'Conferir resposta':s.wrong?'Tentar de novo':s.q===l.qs.length-1?'Concluir aula':'Próxima questão →'}</button></div>`}</section></div>`;$('#close').onclick=closeLesson;$('#practice')?.addEventListener('click',()=>{s.step='quiz';showLesson()});$('#theory')?.addEventListener('click',()=>{s.step='read';showLesson()});$('#finish')?.addEventListener('click',closeLesson);$('#modal').querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{s.selected=+b.dataset.answer;showLesson()});$('#check')?.addEventListener('click',check);$('#close').focus()}
function check(){let s=session,q=lessons[s.i].qs[s.q],p=person();if(!s.checked){s.checked=true;s.wrong=s.selected!==q[2];if(s.wrong&&!p.mistakes.some(m=>m.l===s.i&&m.q===s.q)){p.mistakes.push({l:s.i,q:s.q});save()}}else if(s.wrong){s.checked=false;s.selected=null;s.wrong=false}else{p.mistakes=p.mistakes.filter(m=>!(m.l===s.i&&m.q===s.q));if(s.q<lessons[s.i].qs.length-1){s.q++;s.checked=false;s.selected=null}else{let today=dayKey();if(!p.done.includes(s.i)){p.done.push(s.i);s.award=30}else if(s.rev&&p.reviews[s.i]!==today){s.award=5;p.reviews[s.i]=today}p.xp+=s.award;if(s.award)p.days[today]=(p.days[today]||0)+s.award;s.step='finish';save();render()}}showLesson()}
function closeLesson(){$('#modal').innerHTML='';session=null;render()}
document.addEventListener('keydown',e=>{if(!session)return;if(e.key==='Escape')closeLesson();if(e.key==='Tab'){let focus=[...$('#modal').querySelectorAll('button:not(:disabled),input,select,a[href]')];let a=focus[0],b=focus.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus()}}});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;render();window.scrollTo(0,0)}if(b.dataset.category){category=b.dataset.category;render()}if(b.dataset.lesson!==undefined)start(+b.dataset.lesson);if(b.dataset.review!==undefined)start(+b.dataset.review,true);if(b.dataset.profile!==undefined){db.active=+b.dataset.profile;save();render()}if(b.dataset.delete!==undefined){db.topics.splice(+b.dataset.delete,1);save();render()}if(b.id==='export'){let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='passo-progresso-'+dayKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
document.addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();let f=new FormData(e.target),name=String(f.get('name')).trim();if(!name)return;person().name=name;person().goal=+f.get('goal');save();render();toast('Ajustes salvos. Seu ritmo, suas regras.')}if(e.target.id==='topic-form'){e.preventDefault();let t=String(new FormData(e.target).get('topic')).trim();if(t){(db.topics??=[]).push(t);save();render()}}});
function validBackup(v){return v&&[0,1].includes(v.active)&&Array.isArray(v.profiles)&&v.profiles.length===2&&(!v.topics||(Array.isArray(v.topics)&&v.topics.every(x=>typeof x==='string'&&x.length<=100)))&&v.profiles.every(p=>typeof p.name==='string'&&p.name.trim().length>0&&p.name.length<=35&&Number.isInteger(p.xp)&&p.xp>=0&&[30,60,90].includes(p.goal)&&Array.isArray(p.done)&&new Set(p.done).size===p.done.length&&p.done.every(i=>Number.isInteger(i)&&i>=0&&i<lessons.length)&&p.days&&typeof p.days==='object'&&Object.entries(p.days).every(([d,n])=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isInteger(n)&&n>=0)&&p.reviews&&typeof p.reviews==='object'&&Array.isArray(p.mistakes)&&p.mistakes.every(m=>Number.isInteger(m.l)&&m.l>=0&&m.l<lessons.length&&Number.isInteger(m.q)&&m.q>=0&&m.q<3))}
document.addEventListener('change',async e=>{if(e.target.id==='profile'){db.active=+e.target.value;save();render()}if(e.target.id==='import'){try{let file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error();let imported=JSON.parse(await file.text());if(!validBackup(imported))throw Error();if(confirm('Substituir o progresso dos dois perfis neste navegador pelo arquivo importado?')){db=imported;save();render();toast('Progresso importado.')}}catch{toast('Arquivo inválido. Escolha um backup exportado pelo Passo.')}}});
render();
